const supabaseResult = $input.item.json;
const loopItem = $('Batch Process Leads').item.json;

const is_duplicate = !!supabaseResult.error;

return {
  ...loopItem,
  is_hot: loopItem.lead_tier === 'HOT' && !!loopItem.email,
  is_duplicate: is_duplicate,
  supabase_id: supabaseResult.id || null,
  company_name_raw: loopItem.company_name
};

const data = $json;

return {
  action: data.action,
  lead_id: data.lead_id,
  chat_id: data.chat_id,
  message_id: data.message_id,
  callback_query_id: data.callback_id
};

// Run Once for All Items.
// Get Research from Supabase can return multiple rows for the same lead_id
// if Agent 2 was re-run for testing — this node collapses them down to
// exactly one: the most recently analyzed record.
const lead = $('Retrieve Lead Research').first().json;
const researchRows = $('Retrieve Research Data').all().map(i => i.json);
const routeAction = $('Determine Next Action').first().json;

if (researchRows.length === 0) {
  throw new Error('No research record found for lead_id: ' + routeAction.lead_id);
}

const research = researchRows.reduce((latest, row) =>
  new Date(row.analyzed_at) > new Date(latest.analyzed_at) ? row : latest
);

return [{
  json: {
    lead_id:           routeAction.lead_id,
    research_id:       research.id,
    chat_id:           String(routeAction.chat_id),
    company_name:      lead.company_name || '',
    website:           lead.website || '',
    email:             lead.email || '',
    content:           research.content || '',
    pain_points:       research.pain_points || '',
    automation_gaps:   research.automation_gaps || '',
    review_patterns:   research.review_patterns || '',
    social_signals:    research.social_signals || '',
    google_rating:     research.google_rating != null ? Number(research.google_rating) : null,
    review_count:      research.review_count != null ? Number(research.review_count) : null,
    site_confidence:   research.site_confidence || '',
    review_confidence: research.review_confidence || ''
  }
}];

// Get Proposal from Supabase and Get Lead Email do not pass through input
// fields, so we read from each node explicitly by name — same pattern
// used throughout Agents 2 and 3.
const proposal = $('Retrieve Proposal Data').item.json;
const lead = $('Fetch Lead Email').item.json;
const routeAction = $('Determine Next Action').item.json;

// kp_text was stored as "Subject: <subject>\n\n<body>" — split it back apart.
const kpText = proposal.kp_text || '';
const subjectMatch = kpText.match(/^Subject:\s*(.+)/);
const subject = subjectMatch ? subjectMatch[1].trim() : `Proposal for ${lead.company_name}`;
const body = kpText.replace(/^Subject:.*\n\n/, '').trim();

if (!lead.email || lead.email === 'Not found') {
  throw new Error('No valid email found for lead_id: ' + proposal.lead_id);
}

return {
  proposal_id:  routeAction.lead_id,
  lead_id:      proposal.lead_id,
  chat_id:      routeAction.chat_id,
  company_name: lead.company_name,
  email:        lead.email,
  subject:      subject,
  body:         body
};

// Chain / franchise detection — Tier 1 (free heuristics only).
// Runs BEFORE Lead Scoring. Adds two new fields — chain_signal and
// chain_signal_reason — WITHOUT touching lead_score itself. This keeps
// "popularity" and "chain probability" as two independent dimensions,
// per the decision to not blend them into one additive formula.
//
// Tier 2 (paid Serper verification search, e.g. "[name] chain OR group OR
// owned by") is a SEPARATE later node that should only fire when
// chain_signal === 'suspected' and email/URL checks came back clean —
// that's where Dishoom/Duck & Waffle-style cases (clean-looking own domain,
// no numeric email, no group keyword in path) get caught. Not built yet.

const data = $json;

// --- Tier-0: known chain/group corporate email domains ---
// Cheap catch for repeat offenders we've already identified manually.
// This list is NOT meant to be exhaustive or to scale on its own —
// generalizable detection lives in checks 2-4 below.
const KNOWN_CHAIN_DOMAINS = [
  'greeneking.co.uk',
  'ivycollection.com',
  'samba-brands.com',
  'caledonianheritable.co.uk',
  'carlowriegroup.com'
];

// Generic words stripped out before comparing company name tokens to a domain,
// so e.g. "hotel" or "group" in a name doesn't itself trigger a false overlap.
const STOPWORDS = [
  'the', 'and', 'bar', 'pub', 'cafe', 'grill', 'house', 'kitchen',
  'restaurant', 'hotel', 'inn', 'group', 'company', 'ltd', 'limited',
  'llc', 'llp', 'co'
];

function extractEmailDomain(email) {
  const match = (email || '').match(/@([^\s@]+)$/);
  return match ? match[1].toLowerCase() : null;
}

function extractUrlParts(url) {
  if (!url || url === 'Not found') return { domain: null, path: '' };
  // Regex-based extraction — new URL() is unreliable in n8n's Code node sandbox
  // (silently returns null via catch), so we never use it for domain parsing.
  const match = url.match(/^(?:https?:\/\/)?(?:www\.)?([^\/?#]+)([^?#]*)/i);
  if (!match) return { domain: null, path: '' };
  return { domain: match[1].toLowerCase(), path: (match[2] || '').toLowerCase() };
}

function getNameTokens(name) {
  if (!name || name === 'Not found') return [];
  return name.toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(t => t.length >= 3 && !STOPWORDS.includes(t));
}

const reasons = [];
let strongSignal = false;
let weakSignalCount = 0;

// --- Check 1: known chain email domain (Tier-0, strong) ---
const emailDomain = extractEmailDomain(data.email);
if (emailDomain && KNOWN_CHAIN_DOMAINS.some(d => emailDomain === d || emailDomain.endsWith('.' + d))) {
  strongSignal = true;
  reasons.push(`email domain "${emailDomain}" matches known chain domain list`);
}

// --- Check 2: numeric local-part in email (strong, generalizable) ---
// Pattern like "1234@greeneking.co.uk" — a near-universal branch-numbering
// signal for franchise/chain systems, independent of which domain it is.
if (data.email && data.email !== 'Not found' && /^\d+@/.test(data.email.trim())) {
  strongSignal = true;
  reasons.push('email local-part is purely numeric (branch code pattern)');
}

// --- Check 3: URL path suggests a subpage of a broader group/hotel domain (weak) ---
const CHAIN_PATH_KEYWORDS = [
  'hotel', 'hotels', 'collection', 'group', 'brands', 'resort', 'resorts',
  'townhouse', 'venues', 'locations', 'restaurants', 'pubs', 'inns', 'estates'
];
const { domain, path } = extractUrlParts(data.website);
const pathSegments = path.split('/').filter(Boolean);
const hasChainKeyword = CHAIN_PATH_KEYWORDS.some(kw => path.includes(kw));
const isDeepPath = pathSegments.length >= 3;

if (domain && (hasChainKeyword || isDeepPath)) {
  weakSignalCount++;
  const why = [];
  if (hasChainKeyword) why.push('path contains a group/hotel/chain keyword');
  if (isDeepPath) why.push(`path is ${pathSegments.length} segments deep`);
  reasons.push(`website URL looks like a subpage of a broader domain (${why.join('; ')})`);
}

// --- Check 4: company name shares no tokens with its own domain (weak) ---
if (domain) {
  const nameTokens = getNameTokens(data.company_name);
  const normalizedDomain = domain.replace(/[^a-z0-9]/g, '');
  const hasOverlap = nameTokens.some(t => normalizedDomain.includes(t));
  if (nameTokens.length > 0 && !hasOverlap) {
    weakSignalCount++;
    reasons.push(`company name "${data.company_name}" shares no tokens with its own domain "${domain}"`);
  }
}

// --- Combine into a single categorical signal ---
// - Any strong signal alone => confirmed
// - Two weak signals together => confirmed (compounding)
// - One weak signal alone => suspected (escalate to review, don't auto-reject)
// - Nothing triggered => none
let chainSignal = 'none';
if (strongSignal || weakSignalCount >= 2) {
  chainSignal = 'confirmed';
} else if (weakSignalCount === 1) {
  chainSignal = 'suspected';
}

data.chain_signal = chainSignal;
data.chain_signal_reason = reasons.length > 0 ? reasons.join('; ') : 'no chain indicators found';

return data;

// Contact Domain Check — Category 2 fix (contact-extraction bug).
// Runs after Assemble Lead, alongside Chain Detection Check (order between the
// two doesn't matter — both read the same input fields and write independent
// output fields). Does NOT touch lead_score — same principle as chain_signal:
// flag for human review, don't auto-filter or auto-correct score, until the
// signal has been validated on real, unseen data via a regression test.

const data = $json;

// Same personal-provider regex as Lead Scoring — intentionally NOT expanded or
// improved here, to avoid ending up with two diverging definitions of
// "personal email" in the system. If the list ever needs to grow, update both
// places together in the same session.
const PERSONAL_PROVIDER_REGEX = /gmail|yahoo|hotmail|outlook\.com/;

function extractDomain(url) {
  if (!url || url === 'Not found') return null;
  // Regex-based extraction — new URL() is unreliable in n8n's Code node
  // sandbox (silently returns null via catch), so never used for domain parsing.
  const match = url.match(/^(?:https?:\/\/)?(?:www\.)?([^\/?#]+)/i);
  return match ? match[1].toLowerCase() : null;
}

function extractEmailDomain(email) {
  const match = (email || '').match(/@([^\s@]+)$/);
  return match ? match[1].toLowerCase() : null;
}

// Suffix-based comparison so subdomains count as a match
// (e.g. booking.societyedinburgh.com vs societyedinburgh.com).
// Not a full public-suffix-list implementation — good enough to catch
// genuinely unrelated domains without pulling in an external dependency.
function domainsRelated(domainA, domainB) {
  if (!domainA || !domainB) return false;
  if (domainA === domainB) return true;
  return domainA.endsWith('.' + domainB) || domainB.endsWith('.' + domainA);
}

let contactSignal;
let contactSignalReason;

const hasEmail = data.email && data.email !== 'Not found';

if (!hasEmail) {
  contactSignal = 'unverifiable';
  contactSignalReason = 'no email on file';
} else if (PERSONAL_PROVIDER_REGEX.test(data.email)) {
  contactSignal = 'personal_provider';
  contactSignalReason = 'email is on a personal provider (gmail/yahoo/hotmail/outlook) — not comparable to a site domain';
} else {
  const emailDomain = extractEmailDomain(data.email);
  const siteDomain = extractDomain(data.website);

  if (!siteDomain) {
    contactSignal = 'unverifiable';
    contactSignalReason = 'no website on file to compare the email domain against';
  } else if (domainsRelated(emailDomain, siteDomain)) {
    contactSignal = 'verified';
    contactSignalReason = `email domain "${emailDomain}" matches lead's own site domain "${siteDomain}"`;
  } else {
    contactSignal = 'mismatch';
    contactSignalReason = `email domain "${emailDomain}" does NOT match lead's own site domain "${siteDomain}" — contact may belong to a different business or third-party source`;
  }
}

data.contact_signal = contactSignal;
data.contact_signal_reason = contactSignalReason;

return data;

// Builds a single pre-formatted text block (signal_alert_block) combining
// contact_signal and chain_signal into one Telegram-ready string.
// IMPORTANT: this value gets appended directly to the END of the Score line
// in the Telegram template (not placed on its own template line) — that's
// what makes the empty-string case collapse to zero extra blank lines.
// The leading '\n\n' here is what creates the blank-line separator when
// content exists; there is deliberately no trailing newline, since the
// template's own line break already provides the single line break before
// the next field (LinkedIn).

const data = $json;
const sections = [];

// Contact mismatch first — highest cost of error (wrong email recipient).
if (data.contact_signal === 'mismatch') {
  sections.push(`⚠️ CONTACT MISMATCH\n   ${data.contact_signal_reason}`);
}

// Chain signal second — lower cost of error (a few minutes of manual review).
if (data.chain_signal === 'confirmed' || data.chain_signal === 'suspected') {
  sections.push(`🧩 CHAIN SIGNAL: ${data.chain_signal}\n   ${data.chain_signal_reason}`);
}

data.signal_alert_block = sections.length > 0 ? '\n\n' + sections.join('\n\n') : '';

return data;

// Compare this item's Google place_id against every place_id already
// stored in Supabase (any previous run, any city/niche). Placed right
// after Prepare Keys — BEFORE Serper/Firecrawl — so we never burn API
// credits re-enriching a business we've already processed.
//
// If the lookup came back empty/failed, treat as "not known" — the
// existing unique index on Supabase Insert stays as the safety net,
// so a lookup hiccup here can never silently block a genuinely new lead.

const knownIds = new Set(
  $('Fetch Known Place IDs').all()
    .map(item => item.json.place_id)
    .filter(Boolean)
);

const myPlaceId = $json.place_id;

return {
  ...$json,
  already_known: !!(myPlaceId && knownIds.has(myPlaceId))
};

// Runs once per search, after all "already known" leads from this run
// have been filtered out. Summarizes them into a single count instead
// of sending one Telegram message per duplicate.

const items = $input.all();

return [{
  json: {
    duplicate_count: items.length,
    duplicate_names: items.map(i => i.json.company_name).join(', ')
  }
}];

const data = $json;

function formatItems(raw) {
  if (!raw) return 'Not available';
  let parsed = raw;
  if (typeof raw === 'string') {
    try { parsed = JSON.parse(raw); } catch(e) { return raw; }
  }
  if (Array.isArray(parsed)) {
    return parsed.map(item => {
      if (typeof item === 'string') return `- ${item}`;
      const text = item.point || item.opportunity || item.theme || item.pattern || '';
      const evidence = item.evidence ? ` (Evidence: ${item.evidence})` : '';
      return `- ${text}${evidence}`;
    }).join('\n');
  }
  return String(parsed);
}

return {
  ...data,
  pain_points:     formatItems(data.pain_points),
  automation_gaps: formatItems(data.automation_gaps),
  review_patterns: formatItems(data.review_patterns)
};

// A strict country filter — before Serper/Firecrawl, before scoring.
// Checks the addressComponents (type: "country") of each lead against the expected
// country from the original request. If addressComponents are missing for some reason,
// we skip the lead instead of blindly cutting it (null is better than invalid data
// works both ways: we don't cut it if there's uncertainty).
const expectedCountry = ($('Build Geocode Bounding Box').first().json.country || '').toLowerCase().trim();
const expectedCode = ($('Build Geocode Bounding Box').first().json.country_code || '').toLowerCase().trim();

const out = [];

for (const item of $input.all()) {
  const components = item.json.addressComponents || [];
  const countryComponent = components.find(c => (c.types || []).includes('country'));

  if (!countryComponent) {
    out.push(item);
    continue;
  }

  const longName = (countryComponent.longText || '').toLowerCase().trim();
  const shortCode = (countryComponent.shortText || '').toLowerCase().trim();

  const matches =
    (expectedCountry && longName === expectedCountry) ||
    (expectedCode && shortCode === expectedCode);

  if (matches || (!expectedCountry && !expectedCode)) {
    out.push(item);
  }
}

return out;
